const t={title:"Atomic CRM",description:"A full-featured CRM for personalized solutions."},s={home:"Home",features:"Features",doc:"Doc",pricing:"Pricing",demo:"Demo",github:"Github",industries:"Industries",industryNames:{nonProfit:"Non-Profit CRM",realEstate:"Real Estate CRM",b2b:"B2B CRM",hairSalon:"Hair Salon CRM"}},i={title1:"The Open-Source CRM",title2:"Built Around Your Business",title3:"",description1:"A full-featured CRM tailored to your processes, your team, and your data.",description2:"Own it, host it where you want, and customize it without limits.",getStarted:"Get started",testOnline:"Try it online"},n={tagline:"All the Essentials",title:"A Full-Featured CRM",description:"Atomic CRM offers the key features every team requires.",features:{organizeContacts:{name:"Organize Contacts",description:"Effortlessly organize and access all your contacts in one place, ensuring you have the right information at your fingertips."},createTasks:{name:"Create Tasks and Set Reminders",description:"Stay on top of your to-do list with easy task creation and automated reminders to keep you on track."},takeNotes:{name:"Take Notes",description:"Capture important details and insights with our intuitive note-taking feature, making sure nothing gets lost."},importExport:{name:"Import and Export Data",description:"Seamlessly transfer data in and out of the system with our simple import and export tools, making integration a breeze."},manageDeals:{name:"Manage Deals",description:"Visualize and manage your sales process with our customizable deals pipeline, helping you track progress and close deals faster."},trackActivity:{name:"Track Activity History",description:"Get a comprehensive view of all interactions, including emails, tasks, new deals and contacts, with aggregated activity logs."}}},o={label:"A deal moving through the pipeline, from opportunity to won",stages:["Opportunity","Proposal sent","In negotiation","Won"]},a={tagline:"Improved Workflow",title:"With Advanced Capabilities",description:"Exclusive features designed to improve productivity and collaboration.",features:{sso:{name:"Single-Sign On (SSO)",description:"Log in using your Enterprise Workspace account, including Google, Azure, Keycloak, and Auth0."},kanban:{name:"Kanban Board",description:"Optimize your sales process with a customizable, drag-and-drop card system."},emailToNote:{name:"Email to Note",description:"Include Atomic CRM in your email CC to automatically capture and save communications as notes."},contactAvatars:{name:"Contact Avatars",description:"Enrich contact details by letting the CRM automatically pull avatars from the web using their email."},apiIntegration:{name:"API Integration",description:"Tap into Atomic CRM's API to effortlessly integrate with other systems."},mobileApp:{name:"Mobile App",description:"Access customer data on the go. Dictate notes, manage tasks, even without a connection."},i18n:{name:"Internationalization",description:"Atomic CRM is multilingual-ready, with UI translations and built-in support for localized numbers and dates."}}},r={tagline:"MCP Server",title:"Talk to your CRM",description:"Connect Claude, ChatGPT or any MCP-compatible assistant to Atomic CRM and work with your data in plain language, right where you already work.",features:{ask:{name:"Ask anything",description:"Find contacts, review a pipeline or summarize an account history in seconds, without building a report."},update:{name:"Update by conversation",description:"Log a note, create a task or move a deal to the next stage just by asking."},permissions:{name:"Your data, your permissions",description:"The server runs on your own instance and respects the same access rules as your users."}},cta:"Connect your assistant",videoLabel:"Demo of Atomic CRM with an AI assistant"},l={title:"Built on a Leading-Edge Tech Stack",description:"Atomic CRM uses the latest tech to streamline code and ensure effortless maintenance."},u={title1:"Start And Deploy",title2:"In Minutes",description:"Clone the repo, install dependencies, start local development, and deploy to Supabase and GitHub Pages with one-liners.",link:"Deployment docs"},c={title:"Why choose Atomic CRM?",description:"A CRM you build on, host where you want, and never outgrow.",features:{strongFoundation:{name:"A Strong Foundation",description:"Start with a robust base: Customize your CRM without the hassle of building from scratch."},openSource:{name:"Fully Open-Source",description:"Modify any feature to fit your needs. With open-source flexibility, you're never locked in."},dataOwnership:{name:"Complete Data Ownership",description:"Host with Supabase or on your own infrastructure. Maintain full control over your data and protect against data leakage."},scalability:{name:"Unlimited Scalability",description:"Add unlimited users, leads, and deals. Atomic CRM grows with your business, without any constraints."}}},d={tagline:"Security & Compliance",title:"SOC 2, ISO 27001 & HIPAA Compliant Hosting",description:"Atomic CRM runs on Supabase, a trusted data platform with built-in compliance for regulated industries like healthcare and financial services.",features:{hipaa:{name:"HIPAA Compliant",description:"Handle protected health information with confidence. Supabase offers signed Business Associate Agreements and infrastructure meeting the HIPAA Security Rule requirements."},soc2:{name:"SOC 2 Type II & ISO 27001 Certified",description:"Prove, not just claim, your security posture. Supabase holds both SOC 2 Type II and ISO 27001 certifications, with comprehensive audit logs and database-level access controls."},encryption:{name:"Encryption & Data Protection",description:"All data is encrypted at rest and in transit. Row-level security policies ensure only authorized users access sensitive information."},hosting:{name:"Flexible Hosting Options",description:"Deploy on Supabase's managed cloud with multi-region options, or self-host on your own infrastructure for full data sovereignty."}}},p={settings:{tagline:"Customization made easy",title:"Make the CRM your own, no developer needed",description:"Admins can change the currency, deal stages, pipeline statuses and more from one simple Settings page. The changes apply to the whole team right away.",categories:["Branding","Companies","Deals","Notes","Tasks"],imageAlt:"Settings page: currency, deal stages and pipeline statuses"},tagline:"AI-powered CRM builder",title:"Reshape your CRM With a Simple Prompt",description:"It's like having a development team on call. The built-in AI builds what you ask for, tests it, and explains what changed.",examplesTitle:"Try asking:",examples:["Add a Contracts page listing signed deals","Add a renewal date to companies","Show deals by region on the dashboard","Only let managers delete contacts","Apply our brand guidelines (PDF attached)"],cta:"See how it works",imageAlt:"CRM Builder: a chat to customize the CRM, next to the AI agents working on the requested changes"},m={tagline:"Customer showcase",title:"See what they built with no IT team",description:"Here is what other SMEs shipped in just a few hours."},h={tagline:"Pricing",title:"Free Forever, or Set Up by Experts",description:"Use Atomic CRM for free, or let us set it up on your cloud or infrastructure.",free:{name:"Open-Source",description:"The full power of Atomic CRM, self-managed on your own infrastructure.",price:"Free",features:["Unlimited users, data & storage","Host on Supabase or your own infrastructure","SAML 2.0 single sign-on","Email integration","API access","Community support on GitHub"],cta:"Checkout the code"},setup:{name:"Setup Week",badge:"Done for you",description:"In one week, the team behind Atomic CRM designs, configures, and deploys it for your business, on your cloud or your infrastructure.",price:"Custom quote",period:"One-time fee",includedTitle:"What's included",included:[{name:"Scoping",description:"We map your sales process, team, and needs."},{name:"Specifications",description:"We turn your requirements into a tailored configuration."},{name:"Set-up & deployment",description:"We install and deploy on your cloud or infrastructure."}],closing1:"No subscription. No per-seat pricing. No third-party hosting.",closing2:"Just a customized open-source CRM that you own, set up by CRM experts.",cta:"Book your setup week"}},g={tagline:"Contact",title:"Talk to the team behind Atomic CRM",description:"A question about a feature, a setup, custom development, training or an audit? Tell us about your project and we'll get back to you within 48 hours.",name:"Name",email:"Email",company:"Company (optional)",service:"What do you need?",serviceOther:"Something else",message:"Message (optional)",submit:"Send message",successTitle:"Message sent!",successMessage:"Your email client should have opened with the inquiry. We'll get back to you soon."},f={title1:"Give Atomic CRM a Shot.",title2:"Nothing to lose, plenty to discover.",cta:"Get started"},v={title:"Expertise",description:"We provide expertise to craft it to your needs!",cta:"Order your expert now!",features:{scoping:{name:"Scoping your CRM project",description:"As CRM experts , we can help you define your features, scope your needs and write your product backlog."},customDev:{name:"Custom development",description:"Get tailored CRM solutions built for your specific requirements, by the team behind Atomic CRM, Shadcn Admin Kit, and React-admin."},training:{name:"Training",description:"You need to train one of your team members on Atomic CRM? We are here to help!"},audit:{name:"Audit of code",description:"Ensure code quality and performance with an in-depth code review by our experts."}}},b={trust:{stars:"1,400+ stars on GitHub",licence:"MIT licence",maker:"By Marmelab, the team behind react-admin (25k+ stars)"}},y=JSON.parse(`{"meta":{"title":"Atomic CRM for Hair Salons | Open-Source Hairdresser Software and CRM","description":"Open-source salon management software for hair salons and hairdressers: client files with color formulas, multi-stylist agenda, online booking, reminders, checkout and recalls. No commission, no per-seat fees, your data."},"hero":{"badge":"Open Source · Self-Hosted · Free","title":"The Open-Source CRM for Hair Salons: Keep Every Client Coming Back","subtitle":"Bookings, color formulas, reminders and rebooking in one tool your salon owns. No marketplace commission on your own clients, no per-chair fees, and full control over your data.","getStarted":"Get Started","testOnline":"Test it Online","videoLabel":"Demo of Atomic CRM for hair salons: booking an appointment in three clicks, the client technical file with color formulas, and SMS recalls from the dashboard"},"whyChoose":{"title":"Why Choose Atomic CRM for Your Hair Salon?","intro":"Booking marketplaces charge salons up to 30% on new clients and keep the client relationship for themselves. Atomic CRM is a toolkit you own: start from working hairdresser software, and shape it to the way your salon works.","features":[{"title":"No Commission, No Lock-In","description":"Your clients book on your own page. Open source, self-hosted, and no fee on the clients you already have."},{"title":"Fewer No-Shows","description":"Automatic reminders the day before and two hours before, with one-tap confirm or cancel, and a cancellation policy your front desk can enforce."},{"title":"Formulas That Never Get Lost","description":"Color formulas, processing times and products are saved for every visit, so they no longer live in a notebook or leave with a stylist."},{"title":"Built for the Chair","description":"A mobile mode with large type, the last formula and allergies first, and before/after photos taken right from the phone."},{"title":"Clients Who Come Back","description":"Rebooking suggested at checkout and recalls when a client's usual cycle has passed. Retention becomes routine."},{"title":"Your Salon at a Glance","description":"Today's appointments, free slots, takings, occupancy, no-show and rebooking rates on one screen."}],"photoAlt":"Hairstylist blow-drying a client's hair in a hair salon, a phone within reach on the trolley","phoneAlt":"Hairdresser software chair mode on a phone: client's good-to-know note, new formula button, before and after photo buttons and the last color formula","caption":"Everything a stylist needs between two clients, one-handed."},"essentials":{"title":"Everything Your Hair Salon Needs, From Booking to Rebooking","intro":"A complete salon workflow out of the box: the agenda, the client file, the front desk and the follow-up. Every screen is plain React code you can change.","items":[{"title":"Multi-Stylist Agenda","description":"See the whole team's day in one view, with one column per stylist. Services are made of work and processing time, so a stylist can start the next client while a color processes. Drag to move or resize an appointment. Absences and off-hours are greyed out, and a week view shows each stylist's schedule.","alt":"Hair salon team member profile with Profile, Schedule and Absences tabs showing a weekly schedule"},{"title":"Book in Three Clicks","description":"Click a free slot, find the client by name or phone (or create one on the spot), and add one or more services. Conflicts with other bookings are flagged before you save.","alt":"Quick booking form over the hair salon agenda, with a dashed preview block sized to the selected services"},{"title":"A Technical File for Every Client","description":"Each visit records a structured formula: technique, brand, shades and proportions, developer, processing time, products. Changes from the previous visit are highlighted, and \\"Reuse last formula\\" pre-fills the next one. Allergies and patch tests stay in a red banner at the top of the file, visible to stylists and managers only.","alt":"Client file in the hairdresser software with an allergy banner, visit stats and a color formula timeline highlighting changes from the previous visit"},{"title":"Online Booking on Your Own Page","description":"Clients book in four mobile-friendly steps: services, stylist or \\"no preference\\", time slot, then name and phone with a verification code. No account to create, and the cancellation policy is shown before they confirm. Share it with a link or a QR code on Instagram, Google or the shop window.","alt":"Hair salon online booking page on a phone, step 2 of 4: choose your stylist or no preference"},{"title":"Reminders and Messages","description":"Reminders the day before and two hours before, review requests after the visit, recalls and birthday messages are generated from editable templates. The confirmation status appears on each appointment. In the demo, every message lands in an outbox so you can see what would be sent.","alt":"Appointment details with services, total and reminder statuses"},{"title":"Today's Dashboard","description":"Start the day with today's appointments, free slots per stylist, takings so far, and the clients due for a recall, each with one-click SMS or booking. Weekly indicators compare revenue, occupancy, no-show and rebooking rates with the previous week.","alt":"Hair salon Today dashboard with the appointment timeline, takings, free slots, recalls of the day and weekly KPIs"},{"title":"Services and Team","description":"Build the service catalog with durations, prices, processing segments, eligible stylists and return cycles. Manage each team member's weekly schedule, absences and role (front desk, stylist, manager) from tabs on their profile.","alt":"Hair salon service catalog grouped by category with durations, prices and eligible stylists"}]},"buildNext":{"title":"What You Can Add to Your Hairdresser Software","intro":"Because Atomic CRM is a toolkit and not a closed product, your team or your agency can add what your salon needs, on top of the same data model.","items":[{"title":"Deposits and No-Show Protection","description":"Card imprint or deposit for long services or unreliable clients, with a reliability score per client."},{"title":"Waitlist","description":"Offer freed-up slots automatically to clients who asked to be notified."},{"title":"Gift Cards, Packages and Loyalty Points","description":"Prepaid bundles (e.g. 10 blow-dries), balances visible at checkout."},{"title":"Commissions","description":"Rules per service category, product sales and tiers, with a monthly statement per stylist."},{"title":"Retail and Stock","description":"Product catalog, stock alerts, color consumption per service and supplier orders."},{"title":"Multi-Location","description":"Shared client base, consolidated reporting, stylists working across salons."},{"title":"More Booking Channels","description":"Reserve with Google, WhatsApp booking, or a phone assistant using the built-in MCP server."},{"title":"Real Payments and Certified Checkout","description":"Connect a payment terminal and a certified POS provider where required (for example NF525 in France)."}]},"notJustSalons":{"title":"Not Just Hair Salons","text":"Hair-specific knowledge (formula fields, service categories, return cycles, message templates) lives in one swappable configuration pack. The rest is a generic core for any appointment-based business: barbers, beauty and nail salons, spas, physiotherapists, pet groomers or tattoo studios.","businesses":[{"label":"Barbers","alt":"Barber trimming a client's hair with clippers and a comb"},{"label":"Nail Salons","alt":"Nail technician filing a client's nails at a manicure table"},{"label":"Spas and Beauty Salons","alt":"Beautician giving a facial massage to a client lying under a towel"}]},"getStarted":{"title":"From the Demo to Your Salon","intro":"Your salon can go from the demo to its own CRM in four steps, with our team or with your own developer.","items":[{"title":"Explore the Demo","description":"Book appointments, fill in a color formula, check out a client and send recalls in a fictional Paris salon, with nothing to install.","linkLabel":"Open the demo"},{"title":"Scope Your Salon","description":"We map how your salon works (services, team, booking rules, messages) and adapt the CRM to its specifics before going live.","linkLabel":"Book a Setup Week"},{"title":"Bring Your Clients","description":"The onboarding wizard imports your client list from a CSV file, with presets for Planity and Treatwell exports, and merges duplicates.","linkLabel":"Import guide"},{"title":"Go Live","description":"Share your booking link and QR code on Instagram, Google and the shop window, then invite the front desk, stylists and managers.","linkLabel":"Deployment guide"}]},"pricingTitle":"Hair Salon CRM Pricing","faq":{"title":"Hair Salon CRM: Frequently Asked Questions","items":[{"question":"What is hairdresser software, and why choose an open-source one?","answer":"Hairdresser software, also called salon management software or a hair salon CRM, brings together the agenda, client files with their color formulas, online booking, reminders and checkout. Many salon software vendors charge a monthly fee per stylist or a commission on online bookings. Open-source hairdresser software like Atomic CRM is yours: no commission, no per-chair fee, and code you can adapt to the way your salon works."},{"question":"Is Atomic CRM really free for a hair salon?","answer":"The code is open source under the MIT licence: no commission on bookings, no fee per chair or per stylist, and no paid module. You pay for what you choose to run it with: hosting, SMS credits from your provider, and the time to set it up, by your own developer or during a Setup Week with our team."},{"question":"Can I use it in my salon today?","answer":"Almost. The salon CRM can nearly be deployed as is. We still recommend starting with a scoping phase: we map how your salon works (services, team, booking rules, messages) and adapt the CRM to it before going live. That is what the Setup Week is for."},{"question":"Can I import my clients from Planity or Treatwell?","answer":"Yes. The onboarding wizard reads a CSV file of clients, recognizes Planity and Treatwell exports automatically, lets you adjust the column mapping, and merges duplicates. Any other software that exports a CSV file works with the generic preset."},{"question":"Do my clients need an account to book online?","answer":"No. They pick services, a stylist or no preference and a time slot, then confirm with their name and phone number and a verification code. The cancellation policy is shown before they confirm, and reminders link to a page where they can confirm or cancel."},{"question":"Does it replace my cash register?","answer":"Not on its own. Checkout handles services, products, discounts, tips and split payments, but in countries that require a certified cash register (NF525 in France), you must connect a certified POS provider. Connecting a payment terminal is also an extension to build."},{"question":"How does it handle GDPR and client allergies?","answer":"Each client records SMS and e-mail consents with their date and origin, and you can export or anonymize a client's data in one click. Allergies and patch tests appear in a red banner on the client file, visible to stylists and managers only, not to the front desk."},{"question":"Does it work for a salon with several locations?","answer":"The demo manages one salon with its team, schedules, absences and roles (front desk, stylist, manager). A shared client base across several salons, with consolidated reporting and stylists moving between locations, is an extension you can build on the same data model."}]},"cta":{"title":"Try the Hairdresser Software Demo","text":"Explore a fictional Paris salon with 5 stylists, 150 clients and a full agenda, right in your browser. The data resets on every reload.","testOnline":"Test it Online","talkToExpert":"Talk to an Expert"}}`),w=JSON.parse(`{"meta":{"title":"Atomic CRM for Real Estate Agencies | Open-Source Real Estate CRM Toolkit","description":"Open-source CRM for real estate agencies: properties, mandates, portal leads, buyer matching, visits, offers and the sales pipeline. Self-hosted, no per-seat fees.","ogImageAlt":"Bright apartment living room"},"hero":{"badge":"Open Source · Self-Hosted · Free","title":"The Open-Source CRM for Real Estate Agencies: From Mandate to Final Deed","subtitle":"Properties, mandates, portal leads, buyer matching, visits and offers in one tool your agency owns. No per-agent fees, no listing lock-in, and your client file stays yours.","getStarted":"Get Started","testOnline":"Test it Online","imageAlt":"Sales pipeline in the Atomic CRM real estate CRM, from offer to sold"},"whyChoose":{"title":"Why Choose Atomic CRM for Your Real Estate Agency?","intro":"Agency software is often sold per agent and per module, with paid portal gateways, long contracts and painful migrations. Agents end up typing the same data into three tools. Atomic CRM is a toolkit you own: start from a working real estate CRM, and shape it to the way your agency works.","features":[{"title":"No Per-Agent Fees, No Lock-In","description":"Open source and self-hosted. Add agents, assistants and interns without a new licence, and export all your data at any time."},{"title":"Every Lead Answered","description":"Portal enquiries land in one inbox, linked to the right property, checked for duplicates and assigned to an agent automatically. The time since reception is always visible."},{"title":"The Right Buyer for Each Property","description":"Buyer search criteria are matched against your stock in both directions, with a score that explains why a property fits or misses."},{"title":"Sellers Kept in the Loop","description":"Visits, feedback and offers are recorded as they happen, so you can tell an owner exactly where their sale stands."},{"title":"No Missed Deadline","description":"Mandate expiry, cooling-off period, loan condition and deed date are tracked for you, with reminders before it is too late."},{"title":"Your Agency at a Glance","description":"Active mandates, exclusive share, visits, pending offers and fees signed or collected on one screen, for the whole team or one agent."}],"photoAlt":"Real estate agent showing a property on her phone to a young couple","phoneAlt":"Real estate CRM on mobile: the Today view with the day's visits and follow-ups","caption":"Today's visits and follow-ups, one tap to call, text or report."},"essentials":{"title":"Everything Your Real Estate Agency Needs, From Mandate to Final Deed","intro":"A complete agency workflow out of the box: the property file, the mandate, the buyer, the visit, the offer and the deal. Every screen is plain React code you can change.","items":[{"title":"Properties Your Clients Can Picture","description":"Browse your stock as a grid of photo cards and filter it by status, type, sale or rental, city, price range or agent. Each property page gathers photos, surfaces, rooms, energy rating, the owner (a person or an organization such as an SCI) and the full price history, so every price drop is on record.","alt":"Property grid in the real estate CRM, with photos, status badges and filters"},{"title":"Mandates and a Register That Cannot Be Tampered With","description":"Create a simple, exclusive or semi-exclusive mandate from the property page. The register number is assigned automatically and can never be edited, the register exports to CSV, and a renewal task is created 30 days before the mandate expires.","alt":"Real estate mandate register with sequential numbers and expiry badges"},{"title":"One Inbox for Portal Leads","description":"Enquiries from listing portals and your website are parsed into a name, an email, a phone number and the listing they refer to. One click turns a lead into a contact, or merges it with an existing one when the email or phone already exists. New leads are assigned to the property's agent or in rotation across the team.","alt":"Inbox of real estate portal leads with duplicate detection"},{"title":"Buyer Matching That Explains Itself","description":"Record what each buyer is looking for: budget, cities, property types, surface, rooms, energy rating. The property page lists matching buyers, the buyer page lists matching properties, and each match shows which criteria fit and which do not. Plan a visit straight from the list.","alt":"Buyers matching a property in the real estate CRM, with the criteria that fit"},{"title":"Visits With a Report in Ten Seconds","description":"Schedule visits from the property or from a matching buyer. Afterwards, the agent picks Liked, Mixed or Not interested and adds a comment. Feedback adds up on the property page, ready for the next call with the owner.","alt":"Visit report on mobile in three taps"},{"title":"Offers, Counter-Offers and a Clear Sales Pipeline","description":"Every offer and counter-offer is timestamped on the deal and never deleted. Accepting an offer moves the deal forward and puts the property under offer. The Kanban board has five readable stages, from offer to sold or lost, and each card shows the next deadline: end of the cooling-off period, loan condition, final deed. The deal page shows the whole journey as a timeline, with the notary and the mortgage broker in charge.","alt":"Deal page with milestone timeline, offers, notary and broker"},{"title":"Your Agency Dashboard","description":"KPI tiles for mandates, exclusives, visits, pending offers and fees, a monthly fees chart, the active buyer searches and a Needs attention card that lists what to do today: expiring mandates, unanswered leads, close deadlines, properties without a visit for 30 days and visits waiting for a report. Filter it all by agent.","alt":"Real estate agency dashboard with KPIs and a needs attention list"}]},"channels":{"title":"Plugged Into the Way Agents Work","intro":"Agents live in their inbox and on their phone. Atomic CRM meets them there, and every exchange ends up in the client file.","readDoc":"Read the docs","items":[{"title":"Emails Filed Automatically","description":"Add the CRM's address in Bcc when writing to a buyer or an owner, or forward an email you received: it lands as a note on the right contact, and the contact is created if needed."},{"title":"An App in Every Agent's Pocket","description":"Install the CRM on any phone from the browser, without an app store. The Today view lists visits and follow-ups, with one tap to call, text or write the visit report."},{"title":"Your Website and Tools, Through the API","description":"Every screen relies on a documented REST API. Send your website's contact forms to the lead inbox, or connect your telephony and your accounting software."}]},"talkToCrm":{"tagline":"MCP Server and AI Agents","title":"Talk to Your Real Estate CRM","intro":"Agents spend their days on the road, between two visits. With the built-in MCP server, they can ask Claude, ChatGPT or any MCP-compatible assistant about their properties, buyers and deals in plain language, and update the CRM without opening it.","features":[{"title":"Ask Your Pipeline","description":"“Which exclusive mandates expire this month, and which of those properties had no visit in the last 30 days?” “What are the pending offers on the Lyon apartments, and the best one for each?”"},{"title":"Find the Right Buyers","description":"“A 3-room apartment in Annecy just came in at €420,000. Which active buyers match it? Draft a short email for each of them.”"},{"title":"Report From the Car","description":"“Log the visit of 2 rooms open view in Nantes with Janis Kohler: she liked it, worried about the noise, wants a second visit on Saturday.” The assistant records the report and creates the follow-up task."},{"title":"Start the Day Prepared","description":"“List my visits and follow-ups for today with the owner's phone number and the last feedback on each property.”"},{"title":"Your Data, Your Rules","description":"The assistant goes through the same API and permissions as the app. Nothing is copied to a third-party CRM, and you choose which assistant to connect."}],"imageAlt":"A real estate agent asking Claude about expiring mandates, answered from Atomic CRM","imageCaption":"Claude Desktop connected to an Atomic CRM instance. The MCP server runs on the Supabase backend; the online demo keeps its data in your browser and cannot be connected.","cta":"Connect your assistant","builder":{"title":"Reshape the CRM With a Prompt","description":"The same AI-powered builder as on the Atomic CRM home page can extend the real estate CRM for you, test the change and explain it.","examplesTitle":"Try asking:","examples":["Add a key register to properties","Show the fees signed per agent on the dashboard","Send an email alert to matching buyers when a price drops","Only let managers delete mandates"],"cta":"See how it works"}},"buildNext":{"title":"What You Can Build Next on Your Real Estate CRM","intro":"Because Atomic CRM is a toolkit and not a closed product, your team or your agency can add what your market needs, on top of the same data model.","items":[{"title":"Listing Syndication","description":"Publish properties to portals through a standard feed or a syndication service, check mandatory mentions (fees, energy rating) before going live, and track leads and cost per portal."},{"title":"Owner Reports and Portal","description":"A weekly report generated from visits and feedback, sent in one click, or a read-only owner page with a magic link."},{"title":"E-Signature and Documents","description":"Send mandates, visit vouchers and offers for signature through Yousign or DocuSign, with a document checklist per deal stage and a shared file for the notary and the broker."},{"title":"Valuations and Prospecting","description":"Comparable sales from open data (DVF in France) on the property page, valuation reports in PDF, and a call queue for owners who sell on their own."},{"title":"Lettings and Light Property Management","description":"Online tenant applications with document checks, lease generation, check-in and check-out reports with photos, rent receipts and indexation."},{"title":"Alerts and Messaging","description":"Email alerts to buyers when a matching property or a price drop appears, SMS visit confirmations, and a unified inbox for email, SMS and WhatsApp."},{"title":"Compliance","description":"Anti-money-laundering checks (client identification, risk level, register ready for an audit) and tracking of professional cards and mandatory training."},{"title":"Commissions and Invoicing","description":"Fee splits between agents and agencies, targets per agent, invoices and reconciliation with the payments received from the notary."}],"outro":"And with the MCP server and the AI builder described above, many of these can start as a prompt."},"notJustResidential":{"title":"Not Just Residential Agencies","text":"Real estate knowledge (property types and statuses, mandate kinds, deal stages and deadlines, partner types) lives in one swappable configuration pack, editable in the Settings page. The rest is a generic core for any business that sells or rents assets to clients: commercial real estate brokers, new-build developers and property managers, and beyond real estate, car dealers or yacht brokers.","businesses":[{"label":"Commercial Real Estate","alt":"Empty modern office space for rent"},{"label":"New-Build Sales","alt":"New residential building with a sales agent and a buyer"},{"label":"Lettings and Property Management","alt":"Letting agent doing a check-in inspection with a tenant"}]},"getStarted":{"title":"From the Demo to Your Agency","intro":"Your agency can go from the demo to its own CRM in four steps, with our team or with your own developer.","items":[{"title":"Explore the Demo","description":"Browse properties, match buyers, plan visits and follow offers to the final deed in a fictional French agency, with nothing to install.","linkLabel":"Open the demo"},{"title":"Scope Your Agency","description":"We map how your agency works (property types, mandates, deal stages, lead sources) and adapt the CRM to its specifics before going live.","linkLabel":"Book a Setup Week"},{"title":"Import Your Data","description":"Import contacts, organizations and deals from the CSV files exported by your current software. Properties and mandates can be loaded through the API.","linkLabel":"Import guide"},{"title":"Go Live","description":"Invite every agent, assistant and intern at no extra cost, and have them install the mobile app before their first visit.","linkLabel":"Deployment guide"}]},"pricingTitle":"Real Estate CRM Pricing","faq":{"title":"Real Estate CRM: Frequently Asked Questions","items":[{"question":"What is a real estate CRM, and why choose an open-source one?","answer":"A real estate CRM gathers an agency's properties, mandates, buyers, sellers and deals in one place, and reminds agents of what to do next. Many real estate software vendors charge per agent and keep your data on their servers. An open-source real estate CRM like Atomic CRM is yours: no per-agent fee, hosting where you want, and code you can adapt to the way your agency works."},{"question":"Is Atomic CRM really free for a real estate agency?","answer":"Yes. The code is open source under the MIT licence, with no fee per agent and no paid module. You only pay for hosting: Supabase has a free plan to get started, and its paid plans start at about $25 per month for the whole agency, whatever the number of agents. If you want us to set it up, the Setup Week is a one-time fee."},{"question":"Do I need a developer to use it?","answer":"Not to use it day to day: configuring stages, statuses and types, importing CSV files and managing users all happen in the app. Deploying it takes a few commands that a technical person can run by following the guide. If nobody in your agency is comfortable with that, we can deploy and configure it for you."},{"question":"Can we migrate from our current agency software?","answer":"Contacts, organizations and deals import from CSV files, which most agency software can export. Properties, mandates and their history usually need a migration script written against the REST API. Our team can write it for you as part of a setup project."},{"question":"Does it publish our listings to property portals?","answer":"Not out of the box. Atomic CRM handles the leads coming back from portals: it parses enquiries from SeLoger, Leboncoin, Bien'ici and your website, links them to the property and assigns them to an agent. Publishing listings through a standard feed or a syndication service is one of the extensions you can build on top of the same data."},{"question":"Does it follow French real estate rules?","answer":"The demo is set up for a French agency: a mandate register with sequential numbers that cannot be edited and a CSV export, the 10-day cooling-off period, the loan condition and the final deed date, all tracked with reminders. These rules live in a configuration pack, so you can adapt them to another country. It does not replace the advice of your lawyer or your professional body."},{"question":"How does it handle GDPR?","answer":"Each contact records a dated marketing consent, and you can export or anonymize a contact's data in one click, or export the whole database. Since you host the CRM, you choose where your data lives, including in the European Union, and no third-party vendor has access to your client file."},{"question":"Is it suited to a single agent, or to a network of agencies?","answer":"Both. There is no limit on users, the dashboard and the lists can be filtered by agent, and new leads can be assigned in rotation across the team. For a network with several agencies, separating data between agencies is a customization that the open code makes possible."}]},"cta":{"title":"Try the Real Estate CRM Demo","text":"Explore a fictional French agency with 40 properties across 12 cities, mandates, portal leads, buyer searches, visits, offers and 26 partners, right in your browser, in English or French. The data resets on every reload.","testOnline":"Test it Online","talkToExpert":"Talk to an Expert"}}`),C={copyright:"2026",company:"Marmelab",rights:"All rights reserved."},q={launcherTitle:"Any questions? Ask Jeremie!"},A={meta:t,header:s,hero:i,primaryFeatures:n,kanban:o,secondaryFeatures:a,mcpServer:r,technos:l,deploy:u,why:c,compliance:d,noCode:p,showcase:m,pricing:h,contact:g,callToAction:f,expertise:v,industry:b,hairSalon:y,realEstate:w,footer:C,chatwoot:q},k={title:"Atomic CRM",description:"Un template de CRM open-source pour des solutions personnalisées."},R={home:"Accueil",features:"Fonctionnalités",doc:"Doc",pricing:"Prix",demo:"Démo",github:"Github",industries:"Secteurs",industryNames:{nonProfit:"CRM associatif",realEstate:"CRM immobilier",b2b:"CRM B2B",hairSalon:"CRM salon de coiffure"}},M={title1:"Le CRM open-source",title2:"qui s'adapte",title3:"à votre entreprise",description1:"Un CRM complet, adapté à vos processus, vos équipes et vos données.",description2:"Personnalisez-le sans limites et gardez-en la maîtrise.",getStarted:"Commencer",testOnline:"Démo en ligne"},S={tagline:"Les fonctionnalités essentielles",title:"Un CRM complet",description:"Atomic CRM offre les fonctionnalités clés dont chaque équipe a besoin.",features:{organizeContacts:{name:"Organiser ses contacts",description:"Organisez et accédez facilement à tous vos contacts en un seul endroit."},createTasks:{name:"Créer des tâches et des rappels",description:"Restez au top de votre liste de tâches avec une création facile et des rappels automatisés pour pour ne manquer aucune opportunité."},takeNotes:{name:"Prendre des notes",description:"Capturez les détails et informations importantes avec notre fonction de prise de notes intuitive, pour garder une trace des informations importantes."},importExport:{name:"Importer et exporter des données",description:"Transférez facilement les données vers et depuis le système avec nos outils d'import et d'export simples, rendant l'intégration facile."},manageDeals:{name:"Gérer les opportunités",description:"Visualisez et gérez vos opportunités commerciales avec notre pipeline d'opportunités personnalisable, vous aidant à suivre la progression des opportunités commerciales."},trackActivity:{name:"Suivre l'historique d'activité",description:"Obtenez une vue complète de toutes les interactions, y compris les emails, tâches, nouvelles opportunités et contacts, avec des journaux d'activité agrégés."}}},x={label:"Une affaire qui avance dans le pipeline, de l'opportunité à la signature",stages:["Opportunité","Proposition","Négociation","Gagné"]},z={tagline:"Intégré et automatisé",title:"Avec des capacités avancées",description:"Fonctionnalités exclusives conçues pour améliorer la productivité et la collaboration.",features:{sso:{name:"Authentification Unique (SSO)",description:"Connectez-vous avec votre compte d'entreprise, incluant Google, Azure, Keycloak et Auth0."},kanban:{name:"Tableau Kanban",description:"Optimisez votre processus de vente avec un système de cartes personnalisable en glisser-déposer."},emailToNote:{name:"Email vers note",description:"Incluez Atomic CRM en CC de vos emails pour capturer et sauvegarder automatiquement les communications en notes."},contactAvatars:{name:"Avatars des contacts",description:"Enrichissez les détails des contacts en laissant le CRM récupérer automatiquement les avatars depuis le web via leur email."},apiIntegration:{name:"Intégration API",description:"Utilisez l'API d'Atomic CRM pour intégrer facilement d'autres systèmes, offrant un environnement de données cohérent et unifié."},mobileApp:{name:"Application mobile",description:"Accédez aux infos de vos contacts en déplacement, dictez vos notes vos rappels, même hors ligne."},i18n:{name:"Internationalisation",description:"Atomic CRM est prêt pour le multilingue, avec des traductions d'interface et une localisation des nombres et des dates."}}},P={tagline:"Serveur MCP",title:"Parlez à votre CRM",description:"Connectez Claude, ChatGPT ou tout assistant compatible MCP à Atomic CRM et manipulez vos données en langage naturel, là où vous travaillez déjà.",features:{ask:{name:"Posez n'importe quelle question",description:"Retrouvez un contact, passez en revue votre pipeline ou résumez l'historique d'un compte en quelques secondes, sans construire de rapport."},update:{name:"Mettez à jour par la conversation",description:"Ajoutez une note, créez une tâche ou faites avancer un deal à l'étape suivante, simplement en le demandant."},permissions:{name:"Vos données, vos permissions",description:"Le serveur tourne sur votre propre instance et respecte les mêmes règles d'accès que vos utilisateurs."}},cta:"Connecter votre assistant",videoLabel:"Démo d'Atomic CRM avec un assistant IA"},T={title:"Basé sur une stack technologique de pointe",description:"Atomic CRM utilise les dernières technologies pour simplifier le code et assurer une maintenance sans effort."},I={title1:"Démarrez et déployez",title2:"en quelques minutes",description:"Clonez le repo, installez les dépendances, lancez le développement local et déployez sur Supabase et GitHub Pages en une commande.",link:"Déployer en production"},L={title:"Pourquoi choisir Atomic CRM ?",description:"Un CRM sur lequel bâtir, à héberger où vous voulez, et qui grandit avec vous.",features:{strongFoundation:{name:"Une base solide",description:"Commencez avec une base robuste : Personnalisez votre CRM sans partir de zéro."},openSource:{name:"Entièrement open-source",description:"Modifiez n'importe quelle fonctionnalité selon vos besoins. Avec la flexibilité de l'open-source, vous n'êtes jamais enfermé."},dataOwnership:{name:"Propriété complète des données",description:"Hébergez sur Supabase ou dans votre propre infrastructure. Gardez le contrôle total sur vos données et restez souverain dans la gestion de vos données client."},scalability:{name:"Scalabilité illimitée",description:"Ajoutez des utilisateurs, prospects et opportunités illimités. Atomic CRM grandit avec votre entreprise, sans contraintes."}}},E={tagline:"Sécurité & Conformité",title:"Hébergement conforme SOC 2, HIPAA & ISO 27001",description:"Atomic CRM fonctionne sur Supabase, une plateforme de données de confiance avec une conformité intégrée pour les secteurs réglementés comme la santé et les services financiers.",features:{hipaa:{name:"Conforme HIPAA",description:"Gérez les données de santé protégées en toute confiance. Supabase propose des accords de partenariat commercial (BAA) et une infrastructure conforme aux exigences de la règle de sécurité HIPAA."},soc2:{name:"Certifié SOC 2 Type II & ISO 27001",description:"La sécurité de vos données est déjà certifiée. Supabase détient les certifications SOC 2 Type II et ISO 27001, avec des journaux d'audit complets et des contrôles d'accès au niveau de la base de données."},encryption:{name:"Chiffrement & Protection des données",description:"Toutes les données sont chiffrées au repos et en transit. Les politiques de sécurité au niveau des lignes garantissent que seuls les utilisateurs autorisés accèdent aux informations sensibles."},hosting:{name:"Options d'hébergement flexibles",description:"Déployez sur le cloud géré de Supabase avec des options multi-régions, ou auto-hébergez sur votre propre infrastructure pour une souveraineté totale des données."}}},D={settings:{tagline:"Personnalisation facile",title:"Adaptez le CRM à votre entreprise, sans développeur",description:"Les administrateurs modifient la devise, les étapes des deals, les statuts du pipeline et bien plus depuis une simple page de paramètres. Les changements s'appliquent immédiatement à toute l'équipe.",categories:["Image de marque","Sociétés","Deals","Notes","Tâches"],imageAlt:"Page de paramètres : devise, étapes des deals et statuts du pipeline"},tagline:"Créateur de CRM assisté par IA",title:"Transformez votre CRM d'un simple prompt",description:"C'est comme avoir une équipe de développeurs à disposition. L'IA intégrée construit ce que vous demandez, le teste et vous explique ce qui a changé.",examplesTitle:"Essayez par exemple :",examples:["Ajoute une page Contrats avec les deals signés","Ajoute une date de renouvellement aux sociétés","Affiche les deals par région sur le tableau de bord","Seuls les managers peuvent supprimer des contacts","Applique notre charte graphique (PDF joint)"],cta:"Voir comment ça marche",imageAlt:"CRM Builder : une conversation pour personnaliser le CRM, à côté des agents IA qui réalisent les changements demandés"},O={tagline:"Témoignages clients",title:"Ce qu'ils ont construit sans équipe IT",description:"Voici ce que des PMEs ont créé en quelques heures."},N={tagline:"Tarifs",title:"Gratuit pour toujours, ou installé par des experts",description:"Utilisez Atomic CRM gratuitement, ou laissez-nous l'installer sur votre cloud ou votre infrastructure.",free:{name:"Open-Source",description:"Toute la puissance d'Atomic CRM, géré sur votre propre infrastructure.",price:"Gratuit",features:["Utilisateurs, données & stockage illimités","Hébergement sur Supabase ou votre propre infrastructure","Authentification unique SAML 2.0","Intégration email","Accès API","Support communautaire sur GitHub"],cta:"Voir le code"},setup:{name:"Semaine de setup",badge:"Clé en main",description:"En une semaine, l'équipe derrière Atomic CRM conçoit, configure et déploie votre CRM, sur votre cloud ou votre infrastructure.",price:"Sur devis",period:"Paiement unique",includedTitle:"Ce qui est inclus",included:[{name:"Cadrage",description:"Nous analysons votre processus commercial, votre équipe et vos besoins."},{name:"Spécifications",description:"Nous traduisons vos besoins en une configuration sur mesure."},{name:"Installation & déploiement",description:"Nous installons et déployons sur votre cloud ou votre infrastructure."}],closing1:"Pas d'abonnement. Pas de tarif par utilisateur. Pas d'hébergement tiers.",closing2:"Un CRM open-source personnalisé qui vous appartient, installé par des experts du CRM.",cta:"Réservez votre semaine de setup"}},F={tagline:"Contact",title:"Parlez à l'équipe derrière Atomic CRM",description:"Une question sur une fonctionnalité, un setup, du développement sur mesure, une formation ou un audit ? Parlez-nous de votre projet, nous vous répondrons sous 48 heures.",name:"Nom",email:"Email",company:"Entreprise (optionnel)",service:"De quoi avez-vous besoin ?",serviceOther:"Autre chose",message:"Message (optionnel)",submit:"Envoyer le message",successTitle:"Message envoyé !",successMessage:"Votre client email devrait s'être ouvert avec la demande. Nous vous répondrons bientôt."},j={title1:"Essayez Atomic CRM.",title2:"Rien à perdre, beaucoup à découvrir.",cta:"Commencer"},B={title:"Expertise",description:"Nous fournissons l'expertise pour l'adapter a vos besoins !",cta:"Commandez votre expert maintenant !",features:{scoping:{name:"Cadrage de votre projet CRM",description:"En tant qu'experts CRM, nous pouvons vous aider à définir vos fonctionnalités, cadrer vos besoins et rédiger votre backlog produit."},customDev:{name:"Développement sur mesure",description:"Obtenez des solutions CRM sur mesure construites pour vos besoins spécifiques, par l'équipe derrière Atomic CRM, Shadcn Admin Kit et React-admin."},training:{name:"Formation",description:"Vous devez former un membre de votre equipe sur Atomic CRM ? Nous sommes là pour vous aider !"},audit:{name:"Audit de code",description:"Assurez la qualité et la performance du code avec une revue approfondie par nos experts."}}},G={trust:{stars:"Plus de 1 400 étoiles sur GitHub",licence:"Licence MIT",maker:"Par Marmelab, l'équipe derrière react-admin (plus de 25 000 étoiles)"}},W=JSON.parse(`{"meta":{"title":"Atomic CRM pour les salons de coiffure | Logiciel pour coiffeur et CRM open source","description":"Logiciel open source pour coiffeurs et salons de coiffure : fiches clients avec formules de couleur, agenda multi-coiffeurs, réservation en ligne, rappels, encaissement et relances. Sans commission, sans frais par poste, avec vos données."},"hero":{"badge":"Open source · Auto-hébergé · Gratuit","title":"Le CRM des salons de coiffure : clients fidèles, zéro commission","subtitle":"Rendez-vous, formules de couleur, rappels et reprise de rendez-vous dans un outil qui appartient à votre salon. Aucune commission de plateforme sur vos propres clients, aucun frais par fauteuil, et la maîtrise totale de vos données.","getStarted":"Commencer","testOnline":"Démo en ligne","videoLabel":"Démo d'Atomic CRM pour les salons de coiffure : réservation d'un rendez-vous en trois clics, fiche technique du client avec ses formules de couleur, et relances par SMS depuis le tableau de bord"},"whyChoose":{"title":"Pourquoi choisir Atomic CRM pour votre salon de coiffure ?","intro":"Les plateformes de réservation prélèvent jusqu'à 30 % sur les nouveaux clients et gardent la relation client pour elles. Atomic CRM est une boîte à outils qui vous appartient : partez d'un logiciel pour coiffeur qui fonctionne, et adaptez-le à votre façon de travailler.","features":[{"title":"Sans commission, sans dépendance","description":"Vos clients réservent sur votre propre page. Open source, auto-hébergé, et aucun frais sur les clients que vous avez déjà."},{"title":"Moins de rendez-vous manqués","description":"Rappels automatiques la veille et deux heures avant, confirmation ou annulation en un geste, et une politique d'annulation que l'accueil peut faire respecter."},{"title":"Des formules qui ne se perdent plus","description":"Formules de couleur, temps de pose et produits sont enregistrés à chaque visite. Ils ne dorment plus dans un cahier et ne partent plus avec un coiffeur."},{"title":"Pensé pour le fauteuil","description":"Un mode mobile en gros caractères, la dernière formule et les allergies en premier, et des photos avant/après prises directement depuis le téléphone."},{"title":"Des clients qui reviennent","description":"Prochain rendez-vous proposé à l'encaissement et relances quand le cycle habituel d'un client est dépassé. La fidélisation devient une routine."},{"title":"Votre salon en un coup d'œil","description":"Rendez-vous du jour, créneaux libres, chiffre d'affaires, taux d'occupation, de rendez-vous manqués et de reprise sur un seul écran."}],"photoAlt":"Coiffeuse faisant un brushing à une cliente dans un salon de coiffure, un téléphone à portée de main sur la desserte","phoneAlt":"Mode fauteuil du logiciel pour coiffeur sur un téléphone : note « bon à savoir » du client, bouton de nouvelle formule, boutons photo avant et après, et dernière formule de couleur","caption":"Tout ce dont un coiffeur a besoin entre deux clients, d'une seule main."},"essentials":{"title":"Tout ce dont votre salon de coiffure a besoin, de la réservation au prochain rendez-vous","intro":"Un parcours de salon complet, prêt à l'emploi : l'agenda, la fiche client, l'accueil et le suivi. Chaque écran est du code React classique que vous pouvez modifier.","items":[{"title":"Agenda multi-coiffeurs","description":"Voyez la journée de toute l'équipe d'un seul coup d'œil, avec une colonne par coiffeur. Les prestations se composent de temps de travail et de temps de pose : un coiffeur peut s'occuper du client suivant pendant qu'une couleur pose. Glissez pour déplacer ou redimensionner un rendez-vous. Les absences et les heures de fermeture sont grisées, et une vue semaine affiche le planning de chaque coiffeur.","alt":"Profil d'un membre de l'équipe du salon de coiffure avec les onglets Profil, Planning et Absences affichant un planning hebdomadaire"},{"title":"Un rendez-vous en trois clics","description":"Cliquez sur un créneau libre, retrouvez le client par son nom ou son téléphone (ou créez-le sur-le-champ), puis ajoutez une ou plusieurs prestations. Les chevauchements avec d'autres rendez-vous sont signalés avant l'enregistrement.","alt":"Formulaire de réservation rapide au-dessus de l'agenda du salon de coiffure, avec un aperçu en pointillés dimensionné selon les prestations choisies"},{"title":"Une fiche technique pour chaque client","description":"Chaque visite enregistre une formule structurée : technique, marque, nuances et proportions, oxydant, temps de pose, produits. Les changements par rapport à la visite précédente sont mis en évidence, et « Reprendre la dernière formule » pré-remplit la suivante. Allergies et tests d'allergie restent dans un bandeau rouge en haut de la fiche, visible uniquement des coiffeurs et des responsables.","alt":"Fiche client dans le logiciel pour coiffeur avec un bandeau d'allergie, les statistiques de visite et un historique des formules de couleur mettant en évidence les changements depuis la visite précédente"},{"title":"La réservation en ligne sur votre propre page","description":"Les clients réservent en quatre étapes adaptées au mobile : prestations, coiffeur ou « sans préférence », créneau, puis nom et téléphone avec un code de vérification. Aucun compte à créer, et la politique d'annulation est affichée avant la confirmation. Partagez-la par un lien ou un QR code sur Instagram, Google ou la vitrine.","alt":"Page de réservation en ligne du salon de coiffure sur un téléphone, étape 2 sur 4 : choisir son coiffeur ou sans préférence"},{"title":"Rappels et messages","description":"Rappels la veille et deux heures avant, demandes d'avis après la visite, relances et messages d'anniversaire sont générés à partir de modèles modifiables. Le statut de confirmation apparaît sur chaque rendez-vous. Dans la démo, chaque message arrive dans une boîte d'envoi pour que vous voyiez ce qui serait envoyé.","alt":"Détail d'un rendez-vous avec les prestations, le total et le statut des rappels"},{"title":"Le tableau de bord du jour","description":"Commencez la journée avec les rendez-vous du jour, les créneaux libres par coiffeur, le chiffre d'affaires déjà encaissé et les clients à relancer, chacun avec un SMS ou une réservation en un clic. Les indicateurs de la semaine comparent chiffre d'affaires, taux d'occupation, de rendez-vous manqués et de reprise avec la semaine précédente.","alt":"Tableau de bord du jour du salon de coiffure avec la chronologie des rendez-vous, le chiffre d'affaires, les créneaux libres, les relances du jour et les indicateurs de la semaine"},{"title":"Prestations et équipe","description":"Construisez le catalogue de prestations avec durées, prix, temps de pose, coiffeurs habilités et cycles de retour. Gérez le planning hebdomadaire, les absences et le rôle (accueil, coiffeur, responsable) de chaque membre de l'équipe depuis les onglets de son profil.","alt":"Catalogue de prestations du salon de coiffure regroupées par catégorie avec durées, prix et coiffeurs habilités"}]},"buildNext":{"title":"Ce que vous pouvez ajouter à votre logiciel pour coiffeur","intro":"Comme Atomic CRM est une boîte à outils et non un produit fermé, votre équipe ou votre agence peut ajouter ce dont votre salon a besoin, sur le même modèle de données.","items":[{"title":"Acomptes et protection contre les absences","description":"Empreinte bancaire ou acompte pour les prestations longues ou les clients peu fiables, avec un score de fiabilité par client."},{"title":"Liste d'attente","description":"Proposez automatiquement les créneaux libérés aux clients qui ont demandé à être prévenus."},{"title":"Cartes cadeaux, forfaits et points de fidélité","description":"Forfaits prépayés (par exemple 10 brushings), soldes visibles à l'encaissement."},{"title":"Commissions","description":"Règles par catégorie de prestation, ventes de produits et paliers, avec un relevé mensuel par coiffeur."},{"title":"Vente de produits et stock","description":"Catalogue produits, alertes de stock, consommation de couleur par prestation et commandes fournisseurs."},{"title":"Plusieurs salons","description":"Fichier clients partagé, reporting consolidé, coiffeurs qui travaillent dans plusieurs salons."},{"title":"Plus de canaux de réservation","description":"Réserver avec Google, réservation par WhatsApp, ou un assistant téléphonique grâce au serveur MCP intégré."},{"title":"Vrais paiements et caisse certifiée","description":"Connectez un terminal de paiement et un logiciel de caisse certifié lorsque c'est obligatoire (par exemple NF525 en France)."}]},"notJustSalons":{"title":"Pas seulement pour les salons de coiffure","text":"Tout ce qui est propre à la coiffure (champs de formule, catégories de prestations, cycles de retour, modèles de messages) tient dans un pack de configuration interchangeable. Le reste est un socle générique pour toute activité sur rendez-vous : barbiers, instituts de beauté et ongleries, spas, kinésithérapeutes, toiletteurs ou studios de tatouage.","businesses":[{"label":"Barbiers","alt":"Barbier coupant les cheveux d'un client à la tondeuse et au peigne"},{"label":"Ongleries","alt":"Prothésiste ongulaire limant les ongles d'une cliente à une table de manucure"},{"label":"Spas et instituts de beauté","alt":"Esthéticienne faisant un massage du visage à une cliente allongée sous une serviette"}]},"getStarted":{"title":"De la démo à votre salon","intro":"Votre salon passe de la démo à son propre CRM en quatre étapes, avec notre équipe ou avec votre propre développeur.","items":[{"title":"Explorer la démo","description":"Prenez des rendez-vous, remplissez une formule de couleur, encaissez un client et envoyez des relances dans un salon parisien fictif, sans rien installer.","linkLabel":"Ouvrir la démo"},{"title":"Cadrer votre salon","description":"Nous analysons le fonctionnement de votre salon (prestations, équipe, règles de réservation, messages) et adaptons le CRM à ses spécificités avant la mise en service.","linkLabel":"Réserver une Setup Week"},{"title":"Importer vos clients","description":"L'assistant de démarrage importe votre fichier clients depuis un CSV, avec des préréglages pour les exports Planity et Treatwell, et fusionne les doublons.","linkLabel":"Guide d'import"},{"title":"Mettre en ligne","description":"Partagez votre lien de réservation et votre QR code sur Instagram, Google et en vitrine, puis invitez l'accueil, les coiffeurs et les responsables.","linkLabel":"Guide de déploiement"}]},"pricingTitle":"Tarifs du logiciel pour salon de coiffure","faq":{"title":"Questions fréquentes sur le logiciel pour salon de coiffure","items":[{"question":"Qu'est-ce qu'un logiciel pour coiffeur, et pourquoi le choisir open source ?","answer":"Un logiciel pour coiffeur, ou logiciel de salon de coiffure, réunit l'agenda, les fiches clients avec leurs formules de couleur, la réservation en ligne, les rappels et l'encaissement. Beaucoup de logiciels pour salon de coiffure se paient chaque mois par coiffeur, ou prennent une commission sur les réservations en ligne. Un logiciel pour coiffeur open source comme Atomic CRM vous appartient : aucune commission, aucun frais par fauteuil, et un code que vous pouvez adapter à votre salon."},{"question":"Atomic CRM est-il vraiment gratuit pour un salon de coiffure ?","answer":"Le code est open source sous licence MIT : aucune commission sur les réservations, aucun frais par fauteuil ou par coiffeur, et aucun module payant. Vous payez ce que vous choisissez pour le faire tourner : l'hébergement, les crédits SMS de votre fournisseur, et le temps de mise en place, par votre propre développeur ou pendant une Setup Week avec notre équipe."},{"question":"Puis-je l'utiliser dans mon salon dès aujourd'hui ?","answer":"Presque. Le CRM salon peut quasiment être déployé tel quel. Nous recommandons tout de même de commencer par une phase de cadrage : nous analysons le fonctionnement de votre salon (prestations, équipe, règles de réservation, messages) pour adapter le CRM à ses spécificités avant la mise en service. C'est le rôle de la Setup Week."},{"question":"Puis-je importer mes clients depuis Planity ou Treatwell ?","answer":"Oui. L'assistant de démarrage lit un fichier CSV de clients, reconnaît automatiquement les exports Planity et Treatwell, vous laisse ajuster la correspondance des colonnes et fusionne les doublons. Tout autre logiciel qui exporte un CSV fonctionne avec le préréglage générique."},{"question":"Mes clients doivent-ils créer un compte pour réserver en ligne ?","answer":"Non. Ils choisissent leurs prestations, un coiffeur ou « sans préférence » et un créneau, puis confirment avec leur nom, leur numéro de téléphone et un code de vérification. La politique d'annulation s'affiche avant la confirmation, et les rappels renvoient vers une page pour confirmer ou annuler."},{"question":"Remplace-t-il ma caisse enregistreuse ?","answer":"Pas à lui seul. L'encaissement gère prestations, produits, remises, pourboires et paiements fractionnés, mais dans les pays qui exigent une caisse certifiée (NF525 en France), vous devez connecter un logiciel de caisse certifié. La connexion d'un terminal de paiement est aussi une extension à construire."},{"question":"Comment gère-t-il le RGPD et les allergies des clients ?","answer":"Chaque client enregistre ses consentements SMS et e-mail avec leur date et leur origine, et vous pouvez exporter ou anonymiser les données d'un client en un clic. Les allergies et tests d'allergie s'affichent dans un bandeau rouge sur la fiche client, visible des coiffeurs et des responsables uniquement, pas de l'accueil."},{"question":"Fonctionne-t-il pour un salon avec plusieurs adresses ?","answer":"La démo gère un salon avec son équipe, ses plannings, ses absences et ses rôles (accueil, coiffeur, responsable). Un fichier clients partagé entre plusieurs salons, avec un reporting consolidé et des coiffeurs qui passent d'un salon à l'autre, est une extension que vous pouvez construire sur le même modèle de données."}]},"cta":{"title":"Essayez la démo du logiciel pour coiffeur","text":"Découvrez un salon parisien fictif avec 5 coiffeurs, 150 clients et un agenda bien rempli, directement dans votre navigateur. Les données sont réinitialisées à chaque rechargement.","testOnline":"Démo en ligne","talkToExpert":"Parler à un expert"}}`),H=JSON.parse(`{"meta":{"title":"Atomic CRM pour les agences immobilières | CRM et logiciel immobilier open source","description":"CRM et logiciel immobilier open source pour les agences immobilières : biens, mandats, leads des portails, rapprochement acquéreurs, visites, offres et suivi des ventes. Auto-hébergé, sans frais par utilisateur.","ogImageAlt":"Salon lumineux d'un appartement"},"hero":{"badge":"Open source · Auto-hébergé · Gratuit","title":"Le CRM immobilier open source : du mandat à la remise des clés","subtitle":"Biens, mandats, leads des portails, rapprochement acquéreurs, visites et offres dans un seul outil qui appartient à votre agence. Pas de licence par négociateur, pas de dépendance à un logiciel de transaction, et votre fichier clients reste le vôtre.","getStarted":"Commencer","testOnline":"Tester en ligne","imageAlt":"Pipeline des ventes immobilières dans Atomic CRM, de l'offre à la vente"},"whyChoose":{"title":"Pourquoi choisir Atomic CRM pour votre agence immobilière ?","intro":"Les logiciels immobiliers sont souvent vendus par négociateur et par module, avec des passerelles portails payantes, des contrats longs et des migrations pénibles. Les négociateurs finissent par saisir les mêmes données dans trois outils. Atomic CRM est une boîte à outils qui vous appartient : partez d'un CRM immobilier qui fonctionne, et adaptez-le à la façon dont votre agence travaille.","features":[{"title":"Ni licence par négociateur, ni dépendance","description":"Open source et auto-hébergé. Ajoutez négociateurs, assistants et stagiaires sans nouvelle licence, et exportez toutes vos données à tout moment."},{"title":"Chaque lead traité","description":"Les demandes des portails arrivent dans une seule boîte, rattachées au bon bien, dédoublonnées et attribuées automatiquement à un négociateur. Le délai depuis la réception est toujours visible."},{"title":"Le bon acquéreur pour chaque bien","description":"Les critères de recherche des acquéreurs sont rapprochés de votre stock dans les deux sens, avec un score qui explique pourquoi un bien correspond ou non."},{"title":"Des vendeurs bien informés","description":"Visites, retours et offres sont enregistrés au fil de l'eau : vous pouvez dire à un propriétaire exactement où en est sa vente."},{"title":"Aucune échéance oubliée","description":"Fin de mandat, délai de rétractation SRU, condition suspensive de prêt et date de l'acte sont suivis pour vous, avec des rappels avant qu'il ne soit trop tard."},{"title":"Votre agence d'un coup d'œil","description":"Mandats actifs, part d'exclusivités, visites, offres en cours et honoraires signés ou encaissés sur un seul écran, pour toute l'équipe ou un seul négociateur."}],"photoAlt":"Agente immobilière montrant un bien sur son téléphone à un jeune couple","phoneAlt":"CRM immobilier sur mobile : la vue « Aujourd'hui » avec les visites et relances du jour","caption":"Les visites et relances du jour, en un geste pour appeler, écrire ou faire un compte rendu."},"essentials":{"title":"Tout ce dont votre agence immobilière a besoin, du mandat à la remise des clés","intro":"Un parcours d'agence complet prêt à l'emploi : la fiche du bien, le mandat, l'acquéreur, la visite, l'offre et la vente. Chaque écran est du code React que vous pouvez modifier.","items":[{"title":"Des biens que vos clients peuvent se représenter","description":"Parcourez votre stock sous forme de cartes avec photo et filtrez-le par statut, type, vente ou location, ville, fourchette de prix ou négociateur. Chaque fiche réunit photos, surfaces, pièces, DPE, le propriétaire (une personne ou une structure comme une SCI) et tout l'historique des prix : chaque baisse est tracée.","alt":"Grille des biens dans le CRM immobilier, avec photos, badges de statut et filtres"},{"title":"Des mandats et un registre infalsifiable","description":"Créez un mandat simple, exclusif ou semi-exclusif depuis la fiche du bien. Le numéro d'inscription au registre est attribué automatiquement et ne peut jamais être modifié, le registre s'exporte en CSV, et une tâche de renouvellement est créée 30 jours avant la fin du mandat.","alt":"Registre des mandats immobiliers avec numéros séquentiels et badges d'expiration"},{"title":"Une seule boîte pour les leads des portails","description":"Les demandes des portails d'annonces et de votre site sont analysées pour en extraire le nom, l'e-mail, le téléphone et l'annonce concernée. Un clic transforme un lead en contact, ou le fusionne avec un contact existant quand l'e-mail ou le téléphone sont déjà connus. Les nouveaux leads sont attribués au négociateur du bien ou à tour de rôle dans l'équipe.","alt":"Boîte de réception des leads des portails immobiliers avec détection des doublons"},{"title":"Un rapprochement acquéreurs qui s'explique","description":"Notez ce que cherche chaque acquéreur : budget, villes, types de biens, surface, pièces, DPE. La fiche du bien liste les acquéreurs correspondants, la fiche de l'acquéreur liste les biens correspondants, et chaque rapprochement indique les critères remplis et ceux qui ne le sont pas. Planifiez une visite directement depuis la liste.","alt":"Acquéreurs correspondant à un bien dans le logiciel immobilier, avec les critères remplis"},{"title":"Des visites avec compte rendu en dix secondes","description":"Planifiez les visites depuis le bien ou depuis un acquéreur correspondant. Ensuite, le négociateur choisit Intéressé, Mitigé ou Pas intéressé et ajoute un commentaire. Les retours s'additionnent sur la fiche du bien, prêts pour le prochain appel au propriétaire.","alt":"Compte rendu de visite sur mobile en trois gestes"},{"title":"Offres, contre-offres et un suivi des ventes limpide","description":"Chaque offre et contre-offre est horodatée sur l'affaire et jamais supprimée. Accepter une offre fait avancer l'affaire et passe le bien sous offre. Le tableau Kanban compte cinq étapes lisibles, de l'offre à la vente conclue ou perdue, et chaque carte affiche la prochaine échéance : fin du délai de rétractation, condition suspensive de prêt, acte authentique. La fiche de l'affaire montre tout le parcours sous forme de frise, avec le notaire et le courtier en charge.","alt":"Fiche d'une affaire avec frise des étapes, offres, notaire et courtier"},{"title":"Le tableau de bord de votre agence","description":"Des indicateurs pour les mandats, les exclusivités, les visites, les offres en cours et les honoraires, un graphique mensuel des honoraires, les recherches acquéreurs actives et une carte « À traiter » qui liste ce qu'il faut faire aujourd'hui : mandats qui expirent, leads sans réponse, échéances proches, biens sans visite depuis 30 jours et visites en attente de compte rendu. Le tout filtrable par négociateur.","alt":"Tableau de bord de l'agence immobilière avec indicateurs et liste des points à traiter"}]},"channels":{"title":"Branché sur la façon dont travaillent les négociateurs","intro":"Les négociateurs vivent dans leur boîte mail et sur leur téléphone. Atomic CRM les rejoint là où ils sont, et chaque échange finit dans le dossier client.","readDoc":"Lire la documentation","items":[{"title":"Des e-mails classés automatiquement","description":"Ajoutez l'adresse du CRM en Cci quand vous écrivez à un acquéreur ou à un propriétaire, ou transférez un e-mail reçu : il est enregistré comme note sur le bon contact, créé au besoin."},{"title":"Une application dans la poche de chaque négociateur","description":"Installez le CRM sur n'importe quel téléphone depuis le navigateur, sans passer par un store. La vue Aujourd'hui liste les visites et les relances, à un geste d'un appel, d'un SMS ou du compte rendu de visite."},{"title":"Votre site et vos outils, via l'API","description":"Chaque écran repose sur une API REST documentée. Envoyez les formulaires de contact de votre site dans la boîte des leads, ou connectez votre téléphonie et votre logiciel de comptabilité."}]},"talkToCrm":{"tagline":"Serveur MCP et agents IA","title":"Parlez à votre CRM immobilier","intro":"Les négociateurs passent leurs journées sur la route, entre deux visites. Avec le serveur MCP intégré, ils peuvent interroger Claude, ChatGPT ou tout assistant compatible MCP sur leurs biens, leurs acquéreurs et leurs affaires en langage courant, et mettre à jour le CRM sans l'ouvrir.","features":[{"title":"Interrogez votre pipeline","description":"« Quels mandats exclusifs expirent ce mois-ci, et lesquels de ces biens n'ont eu aucune visite depuis 30 jours ? » « Quelles sont les offres en cours sur les appartements de Lyon, et la meilleure pour chacun ? »"},{"title":"Trouvez les bons acquéreurs","description":"« Un T3 à Annecy vient d'entrer à 420 000 €. Quels acquéreurs actifs correspondent ? Rédige un court e-mail pour chacun d'eux. »"},{"title":"Faites le compte rendu depuis la voiture","description":"« Note la visite du 2 pièces vue dégagée à Nantes avec Janis Kohler : elle a aimé, s'inquiète du bruit, veut une seconde visite samedi. » L'assistant enregistre le compte rendu et crée la tâche de relance."},{"title":"Commencez la journée préparé","description":"« Liste mes visites et relances du jour avec le téléphone du propriétaire et le dernier retour sur chaque bien. »"},{"title":"Vos données, vos règles","description":"L'assistant passe par la même API et les mêmes permissions que l'application. Rien n'est copié dans un CRM tiers, et vous choisissez l'assistant à connecter."}],"imageAlt":"Une négociatrice interroge Claude sur les mandats qui expirent, avec des réponses tirées d'Atomic CRM","imageCaption":"Claude Desktop connecté à une instance d'Atomic CRM. Le serveur MCP tourne sur le backend Supabase ; la démo en ligne garde ses données dans votre navigateur et ne peut pas être connectée.","cta":"Connecter votre assistant","builder":{"title":"Modifiez le CRM avec un prompt","description":"Le même constructeur de CRM piloté par l'IA que sur la page d'accueil d'Atomic CRM peut faire évoluer le CRM immobilier pour vous, tester la modification et l'expliquer.","examplesTitle":"Essayez de demander :","examples":["Ajoute un registre des clés aux biens","Affiche les honoraires signés par négociateur sur le tableau de bord","Envoie une alerte e-mail aux acquéreurs correspondants quand un prix baisse","Réserve la suppression des mandats aux managers"],"cta":"Voir comment ça marche"}},"buildNext":{"title":"Ce que vous pouvez ajouter à votre logiciel immobilier","intro":"Comme Atomic CRM est une boîte à outils et non un produit fermé, votre équipe ou votre agence peut ajouter ce dont votre marché a besoin, sur le même modèle de données.","items":[{"title":"Diffusion des annonces","description":"Publiez les biens sur les portails via un flux standard ou un service de multidiffusion, vérifiez les mentions obligatoires (honoraires, DPE) avant la mise en ligne, et suivez les leads et le coût par portail."},{"title":"Rapports et espace propriétaire","description":"Un rapport hebdomadaire généré à partir des visites et des retours, envoyé en un clic, ou une page propriétaire en lecture seule accessible par lien magique."},{"title":"Signature électronique et documents","description":"Envoyez mandats, bons de visite et offres en signature via Yousign ou DocuSign, avec une liste de pièces par étape de la vente et un dossier partagé avec le notaire et le courtier."},{"title":"Estimations et prospection","description":"Les ventes comparables issues de l'open data (DVF en France) sur la fiche du bien, des avis de valeur en PDF, et une file d'appels pour les particuliers qui vendent seuls."},{"title":"Location et gestion légère","description":"Dossiers de candidature locataires en ligne avec vérification des pièces, génération des baux, états des lieux d'entrée et de sortie avec photos, quittances et révision des loyers."},{"title":"Alertes et messagerie","description":"Des alertes e-mail aux acquéreurs quand un bien correspondant ou une baisse de prix apparaît, des confirmations de visite par SMS, et une boîte unifiée pour l'e-mail, les SMS et WhatsApp."},{"title":"Conformité","description":"Contrôles anti-blanchiment (identification du client, niveau de risque, registre prêt pour un contrôle) et suivi des cartes professionnelles et des formations obligatoires."},{"title":"Commissions et facturation","description":"Partage des honoraires entre négociateurs et agences, objectifs par négociateur, factures et rapprochement avec les paiements reçus du notaire."}],"outro":"Et avec le serveur MCP et le constructeur IA présentés plus haut, beaucoup de ces évolutions peuvent commencer par un prompt."},"notJustResidential":{"title":"Pas seulement pour les agences résidentielles","text":"Le savoir-faire immobilier (types et statuts de biens, types de mandats, étapes et échéances des ventes, types de partenaires, règles françaises comme le registre des mandats et le délai de rétractation de 10 jours) tient dans un pack de configuration remplaçable, modifiable depuis la page Paramètres. Le reste est un socle générique pour toute activité qui vend ou loue des biens à des clients : immobilier d'entreprise, promoteurs de programmes neufs, administrateurs de biens et, au-delà de l'immobilier, concessionnaires automobiles ou courtiers en yachts.","businesses":[{"label":"Immobilier d'entreprise","alt":"Plateau de bureaux moderne et vide à louer"},{"label":"Vente de programmes neufs","alt":"Petit immeuble neuf avec un commercial et un acquéreur"},{"label":"Location et gestion locative","alt":"Agent immobilier faisant un état des lieux d'entrée avec une locataire"}]},"getStarted":{"title":"De la démo à votre agence","intro":"Votre agence passe de la démo à son propre CRM en quatre étapes, avec notre équipe ou avec votre propre développeur.","items":[{"title":"Explorer la démo","description":"Parcourez les biens, rapprochez les acquéreurs, planifiez des visites et suivez les offres jusqu'à l'acte dans une agence française fictive, sans rien installer.","linkLabel":"Ouvrir la démo"},{"title":"Cadrer votre agence","description":"Nous analysons le fonctionnement de votre agence (types de biens, mandats, étapes de vente, sources de leads) et adaptons le CRM à ses spécificités avant la mise en service.","linkLabel":"Réserver une Setup Week"},{"title":"Importer vos données","description":"Importez contacts, organisations et affaires depuis les fichiers CSV exportés par votre logiciel actuel. Les biens et les mandats se chargent via l'API.","linkLabel":"Guide d'import"},{"title":"Mettre en ligne","description":"Invitez tous vos négociateurs, assistants et stagiaires sans surcoût, et faites-leur installer l'application mobile avant leur première visite.","linkLabel":"Guide de déploiement"}]},"pricingTitle":"Tarifs du CRM immobilier","faq":{"title":"Questions fréquentes sur le CRM immobilier","items":[{"question":"Qu'est-ce qu'un CRM immobilier, et pourquoi le choisir open source ?","answer":"Un CRM immobilier, ou logiciel de transaction immobilière, réunit les biens, les mandats, les acquéreurs, les vendeurs et les affaires d'une agence au même endroit, et rappelle aux négociateurs ce qu'ils doivent faire ensuite. Beaucoup de logiciels immobiliers se louent par négociateur et gardent vos données sur leurs serveurs. Un CRM immobilier open source comme Atomic CRM vous appartient : pas de licence par négociateur, un hébergement au choix, et un code que vous pouvez adapter à votre agence."},{"question":"Atomic CRM est-il vraiment gratuit pour une agence immobilière ?","answer":"Oui. Le code est open source sous licence MIT, sans frais par négociateur ni module payant. Vous ne payez que l'hébergement : Supabase propose une offre gratuite pour démarrer, et ses offres payantes commencent autour de 25 $ par mois pour toute l'agence, quel que soit le nombre de négociateurs. Si vous voulez que nous l'installions, la Setup Week est facturée une seule fois."},{"question":"Faut-il un développeur pour l'utiliser ?","answer":"Pas au quotidien : la configuration des étapes, statuts et types, l'import de fichiers CSV et la gestion des utilisateurs se font dans l'application. Le déploiement demande quelques commandes qu'une personne technique peut lancer en suivant le guide. Si personne dans votre agence n'est à l'aise avec cela, nous pouvons le déployer et le configurer pour vous."},{"question":"Peut-on migrer depuis notre logiciel d'agence actuel ?","answer":"Les contacts, organisations et affaires s'importent depuis des fichiers CSV, que la plupart des logiciels d'agence savent exporter. Les biens, les mandats et leur historique demandent en général un script de migration écrit sur l'API REST. Notre équipe peut l'écrire pour vous dans le cadre d'un projet d'installation."},{"question":"Publie-t-il nos annonces sur les portails ?","answer":"Pas tel quel. Atomic CRM traite les leads qui reviennent des portails : il analyse les demandes de SeLoger, Leboncoin, Bien'ici et de votre site, les rattache au bien et les attribue à un négociateur. La diffusion des annonces via un flux standard ou un service de multidiffusion fait partie des extensions que vous pouvez construire sur les mêmes données."},{"question":"Respecte-t-il la réglementation immobilière française ?","answer":"La démo est configurée pour une agence française : un registre des mandats à numérotation continue non modifiable avec export CSV, le délai de rétractation de 10 jours, la condition suspensive de prêt et la date de l'acte authentique, tous suivis avec des rappels. Ces règles vivent dans un pack de configuration, que vous pouvez adapter à un autre pays. Il ne remplace pas les conseils de votre avocat ou de votre fédération professionnelle."},{"question":"Comment gère-t-il le RGPD ?","answer":"Chaque contact enregistre un consentement marketing daté, et vous pouvez exporter ou anonymiser les données d'un contact en un clic, ou exporter toute la base. Comme vous hébergez le CRM, vous choisissez où vivent vos données, y compris dans l'Union européenne, et aucun éditeur tiers n'a accès à votre fichier clients."},{"question":"Convient-il à un agent indépendant ou à un réseau d'agences ?","answer":"Aux deux. Le nombre d'utilisateurs n'est pas limité, le tableau de bord et les listes se filtrent par négociateur, et les nouveaux leads peuvent être attribués à tour de rôle dans l'équipe. Pour un réseau de plusieurs agences, cloisonner les données entre agences est une personnalisation que le code ouvert rend possible."}]},"cta":{"title":"Essayez la démo du CRM immobilier","text":"Explorez une agence française fictive avec 40 biens dans 12 villes, des mandats, des leads de portails, des recherches acquéreurs, des visites, des offres et 26 partenaires, directement dans votre navigateur, en français ou en anglais. Les données sont réinitialisées à chaque rechargement.","testOnline":"Tester en ligne","talkToExpert":"Parler à un expert"}}`),V={copyright:"2026",company:"Marmelab",rights:"Tous droits réservés."},U={launcherTitle:"Des questions ? Demandez à Jeremie !"},Y={meta:k,header:R,hero:M,primaryFeatures:S,kanban:x,secondaryFeatures:z,mcpServer:P,technos:T,deploy:I,why:L,compliance:E,noCode:D,showcase:O,pricing:N,contact:F,callToAction:j,expertise:B,industry:G,hairSalon:W,realEstate:H,footer:V,chatwoot:U},$={en:A,fr:Y};function K(e){return{t:$[e],locale:e}}export{K as u};
